        width: min(100%, 45rem);
        padding: clamp(1.5rem, 4vw, 3rem);
        border: 1px solid rgba(219, 227, 239, 0.82);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
