        font-size: 1.05rem;
        line-height: 1.6;
      }

      .contact-form {
        display: grid;
        gap: 1.15rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-weight: 700;
      }

      .required-note {
        color: var(--muted);
        font-size: 0.95rem;
        font-weight: 500;
