        border-radius: 0.85rem;
        color: var(--text);
        background: #ffffff;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      input::placeholder {
        color: #94a3b8;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px var(--focus);
        outline: none;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .submit-button {
        min-height: 3.3rem;
        margin-top: 0.35rem;
        border: 0;
        border-radius: 999px;
        color: #ffffff;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.26);
        cursor: pointer;
        font-weight: 800;
        transition:
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      .submit-button:hover {
        box-shadow: 0 18px 36px rgba(37, 99, 235, 0.34);
        transform: translateY(-1px);
      }

      .submit-button:focus {
        box-shadow:
          0 0 0 4px var(--focus),
          0 14px 30px rgba(37, 99, 235, 0.26);
        outline: none;
      }

      @media (max-width: 36rem) {
        .page-shell {
          padding: 1rem;
        }

        .support-card {
          border-radius: 1.15rem;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>

    <script>
      const fields = [
        {
          id: "full-name",
          label: "Full name",
          name: "fullName",
          type: "text",
          autocomplete: "name",
          placeholder: "Alex Morgan",
          required: true,
        },
        {
          id: "email-address",
          label: "Email address",
          name: "email",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true,
        },
        {
          id: "phone-number",
          label: "Phone number",
          name: "phone",
          type: "tel",
