  <body>
    <main id="root"></main>

    <script>
      const fields = [
        {
          id: "full-name",
          label: "Full name",
          name: "fullName",
          type: "text",
          autocomplete: "name",
          placeholder: "Alex Morgan",
          required: true,
        },
        {
          id: "email-address",
          label: "Email address",
          name: "email",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true,
        },
        {
          id: "phone-number",
          label: "Phone number",
          name: "phone",
          type: "tel",
          autocomplete: "tel",
          placeholder: "(555) 123-4567",
          helperText: "Use a 10-digit phone number, such as (555) 123-4567.",
          required: false,
        },
      ];

      function Field({ id, label, name, type, autocomplete, placeholder, required, helperText }) {
        const helperId = helperText ? `${id}-helper` : "";

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-note">(required)</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              ${required ? "required" : ""}
              ${helperId ? `aria-describedby="${helperId}"` : ""}
            />
            ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        return `
          <form class="contact-form" action="#" method="post">
            ${fields.map((field) => Field(field)).join("")}
            <button class="submit-button" type="submit">Submit support request</button>
          </form>
        `;
      }

      function SupportPage() {
        return `
          <div class="page-shell">
            <section class="support-card" aria-labelledby="support-title">
              <p class="eyebrow">Support</p>
              <h1 id="support-title">Contact our team</h1>
              <p class="intro">
                Tell us how to reach you and a support specialist will follow up with helpful next steps.
              </p>
              ${ContactForm()}
            </section>
          </div>
        `;
      }

      document.getElementById("root").innerHTML = SupportPage();
    </script>
  </body>
</html>
